// PATCH: liga o ar-condicionado. Espelha a lógica do POST ac/cut (que desliga).
// ADAPTE aqui para o seu atuador real (MQTT, serial, GPIO...). Mantenha as respostas e os cabeçalhos CORS.
const lista=String(env.get('CORS_ORIGINS')||'http://127.0.0.1:5500,http://localhost:5500').split(',').map(x=>x.trim()).filter(Boolean);
const origem=(msg.req&&msg.req.headers&&msg.req.headers.origin)||'';
const h={'Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type, Accept','Access-Control-Max-Age':'600','Vary':'Origin'};
if(lista.includes('*')) h['Access-Control-Allow-Origin']='*'; else if(origem&&lista.includes(origem)) h['Access-Control-Allow-Origin']=origem;
msg.headers=h;
const DEF={ocupada:false,ac:true,modo:'AUTO',potencia:1450,energia:12.34,online:true,ts:Date.now(),oled:''};
const s=global.get('campus')||DEF;
if(String(msg.req.params.room_id)!=='101'){msg.statusCode=404;msg.payload={erro:'sala não encontrada'};return msg;}
if(!s.online){msg.statusCode=503;msg.payload={erro:'dispositivo offline'};return msg;}
s.ac=true; global.set('campus',s);
msg.statusCode=200; msg.payload={ok:true,room_id:101,ac:'ligado'}; return msg;
